-- PostgreSQL migration for a clean installation.  It is intentionally idempotent.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS users (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, email varchar(255) NOT NULL UNIQUE, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, code varchar(50) UNIQUE, parent_id bigint REFERENCES departments(id), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS department_members (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, department_id bigint NOT NULL REFERENCES departments(id), user_id bigint NOT NULL REFERENCES users(id), role varchar(20) NOT NULL CHECK(role IN ('MEMBER','MANAGER','ADMIN')), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(department_id,user_id));
CREATE TABLE IF NOT EXISTS document_types (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL, code varchar(50) UNIQUE, has_correlative boolean NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_sequences (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_type_id bigint NOT NULL REFERENCES document_types(id), department_id bigint REFERENCES departments(id), year integer NOT NULL, last_number integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_document_sequence_scope ON document_sequences(document_type_id,COALESCE(department_id,0),year);
CREATE TABLE IF NOT EXISTS documents (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, document_type_id bigint NOT NULL REFERENCES document_types(id), document_number varchar(150) UNIQUE, created_by bigint NOT NULL REFERENCES users(id), department_id bigint REFERENCES departments(id), name varchar(255) NOT NULL, description text, file_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procedures (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL, procedure_type varchar(12) NOT NULL CHECK(procedure_type IN ('PERSONAL','DEPARTMENT')), created_by bigint NOT NULL REFERENCES users(id), sender_user_id bigint REFERENCES users(id), sender_department_id bigint REFERENCES departments(id), status varchar(10) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')), closed_at timestamptz, closed_by bigint REFERENCES users(id), closing_message_id bigint, closing_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((procedure_type='PERSONAL' AND sender_user_id IS NOT NULL) OR (procedure_type='DEPARTMENT' AND sender_user_id IS NULL AND sender_department_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS messages (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_by bigint NOT NULL REFERENCES users(id), sender_user_id bigint REFERENCES users(id), sender_department_id bigint REFERENCES departments(id), procedure_id bigint REFERENCES procedures(id), message_type varchar(12) NOT NULL CHECK(message_type IN ('PERSONAL','DEPARTMENT')), visibility varchar(12) NOT NULL CHECK(visibility IN ('PRIVATE','DEPARTMENT')), subject varchar(255) NOT NULL, body text NOT NULL, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((message_type='PERSONAL' AND sender_user_id IS NOT NULL AND visibility='PRIVATE') OR (message_type='DEPARTMENT' AND sender_user_id IS NULL AND sender_department_id IS NOT NULL)));
ALTER TABLE procedures DROP CONSTRAINT IF EXISTS fk_procedure_closing_message;
ALTER TABLE procedures ADD CONSTRAINT fk_procedure_closing_message FOREIGN KEY(closing_message_id) REFERENCES messages(id);
CREATE TABLE IF NOT EXISTS message_recipients (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, message_id bigint NOT NULL REFERENCES messages(id) ON DELETE CASCADE, recipient_id bigint REFERENCES users(id), department_id bigint REFERENCES departments(id), type varchar(2) NOT NULL CHECK(type IN ('TO','CC')), status varchar(15) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','READ','IN_PROGRESS','ANSWERED','CLOSED')), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((recipient_id IS NULL) <> (department_id IS NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS uq_message_recipient_user ON message_recipients(message_id,recipient_id) WHERE recipient_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_message_recipient_department ON message_recipients(message_id,department_id) WHERE department_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS message_recipient_reads (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, message_recipient_id bigint NOT NULL REFERENCES message_recipients(id) ON DELETE CASCADE, user_id bigint NOT NULL REFERENCES users(id), read_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_recipient_id,user_id));
CREATE TABLE IF NOT EXISTS message_documents (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, message_id bigint NOT NULL REFERENCES messages(id) ON DELETE CASCADE, document_id bigint NOT NULL REFERENCES documents(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id,document_id));
CREATE TABLE IF NOT EXISTS message_relations (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_message_id bigint NOT NULL REFERENCES messages(id), target_message_id bigint NOT NULL REFERENCES messages(id), relation_type varchar(10) NOT NULL CHECK(relation_type IN ('REPLY','FORWARD','REFERENCE')), created_by bigint NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(source_message_id<>target_message_id), UNIQUE(source_message_id,target_message_id,relation_type));
CREATE TABLE IF NOT EXISTS audit_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id bigint NOT NULL REFERENCES users(id), entity_type varchar(50) NOT NULL, entity_id bigint NOT NULL, action varchar(50) NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS idx_messages_creator ON messages(created_by); CREATE INDEX IF NOT EXISTS idx_messages_sender_user ON messages(sender_user_id); CREATE INDEX IF NOT EXISTS idx_messages_sender_department ON messages(sender_department_id); CREATE INDEX IF NOT EXISTS idx_messages_procedure ON messages(procedure_id); CREATE INDEX IF NOT EXISTS idx_messages_created ON messages(created_at); CREATE INDEX IF NOT EXISTS idx_recipients_status ON message_recipients(status); CREATE INDEX IF NOT EXISTS idx_procedures_creator_status ON procedures(created_by,sender_department_id,status); CREATE INDEX IF NOT EXISTS idx_message_documents_document ON message_documents(document_id); CREATE INDEX IF NOT EXISTS idx_relations_target ON message_relations(target_message_id);


